                : key === 'proof-threshold' ? 'Proof threshold'
                : key === 'note-threshold' ? 'Note threshold'
                : key === 'parent' ? 'Parent sheet'
                : key === 'fiscal-start-month' ? 'Fiscal year start month (1 to 12)'
